"""Authored hotel and automotive layouts for deterministic business briefs."""
from html import escape

HOTEL_ART = '''<svg viewBox="0 0 1200 850" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Original illustration of a coastal hotel"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#b5cbd0"/><stop offset="1" stop-color="#e9d8b9"/></linearGradient><linearGradient id="pool" x2="1" y2="1"><stop stop-color="#6caeae"/><stop offset="1" stop-color="#c0d9ce"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h1200v850H0z"/><circle cx="945" cy="175" r="85" fill="#f5e7ca"/><path fill="#99b7b5" d="M0 430h1200v420H0z"/><path fill="#778f85" d="M0 455q170-145 340 0l70 95H0z"/><path fill="#d0bca0" d="m0 630 1200-75v295H0z"/><path fill="#a68e73" d="m160 300 690-55 130 75v360H160z"/><path fill="#e6d9c2" d="M160 300h650v365H160z"/><path fill="#f3e9d5" d="M115 285h740v28H115zM115 444h740v24H115zM115 625h740v35H115z"/><g fill="#58675d"><path d="M202 342h117v102H202zM366 342h117v102H366zM530 342h117v102H530zM694 342h85v102H694z"/><path d="M202 504q0-35 58-35t59 35v121H202zM366 504q0-35 58-35t59 35v121H366zM530 504q0-35 58-35t59 35v121H530zM694 504q0-35 42-35t43 35v121H694z"/></g><g stroke="#e6d9c2" stroke-width="5"><path d="M261 342v102m164-102v102m164-102v102m148-102v102"/></g><path d="m100 730 625-35 425 120-680 35Z" fill="url(#pool)" stroke="#f2e7d2" stroke-width="16"/><g stroke="#e1eee3" opacity=".6"><path d="m220 748 495-23m-370 47 510-22m-355 48 493-16"/></g><path d="M1000 655q-40-270-5-420" stroke="#776447" stroke-width="19" fill="none"/><g fill="#486853"><path d="M997 245q-150-135-225 0 120-55 225 0ZM997 245q170-130 203 30-100-80-203-30ZM997 245q40-180 123-164-79 47-123 164ZM997 245q-75-174-170-120 123 19 170 120ZM997 245q-115-35-140 112 67-96 140-112ZM997 245q154 2 155 118-65-86-155-118Z"/></g><g fill="#51694e"><ellipse cx="95" cy="638" rx="92" ry="54"/><ellipse cx="860" cy="660" rx="55" ry="34"/></g></svg>'''
AUTO_ART = '''<svg viewBox="0 0 1200 850" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Original illustration of a performance car in a workshop"><defs><linearGradient id="wall" x2="0" y2="1"><stop stop-color="#30383e"/><stop offset="1" stop-color="#12191e"/></linearGradient><linearGradient id="body" x2="0" y2="1"><stop stop-color="#ced6d9"/><stop offset=".5" stop-color="#798a94"/><stop offset="1" stop-color="#3f525e"/></linearGradient><radialGradient id="light"><stop stop-color="#eeb777" stop-opacity=".25"/><stop offset="1" stop-color="#b47b48" stop-opacity="0"/></radialGradient></defs><path fill="url(#wall)" d="M0 0h1200v850H0z"/><ellipse cx="700" cy="360" rx="650" ry="390" fill="url(#light)"/><g stroke="#455057" stroke-width="2"><path d="M0 600h1200M0 100h1200M0 220h1200M0 340h1200M0 460h1200M100 0v600M350 0v600M600 0v600M850 0v600M1100 0v600"/></g><path d="M80 100h470m190 0h470" stroke="#f4d6ac" stroke-width="8"/><path d="m0 850 450-250m750 250L820 600M0 730h1200" stroke="#5a6367" opacity=".3"/><ellipse cx="650" cy="689" rx="510" ry="57" fill="#0a1116"/><path d="m130 585 76-78 157-38 149-134q25-20 70-20h238l170 173 96 28 38 77-33 68H153Z" fill="url(#body)"/><path d="m390 466 143-126h256l130 135Z" fill="#162932" stroke="#b5bfc3" stroke-width="6"/><path d="M665 340v130" stroke="#9babb1" stroke-width="8"/><path d="m511 365 105-9-83 76-93 22Z" fill="#c3d1cd" opacity=".18"/><path d="m146 579 940-31" stroke="#d5dcdc" stroke-width="5"/><path d="m219 548 154-14-7 43-154 11Z" fill="#f6e3bd"/><path d="m1028 542 49 18 8 30-59-7Z" fill="#d47955"/><path d="M463 498v139m360-140v134" stroke="#435762" stroke-width="3"/><path d="M682 493h48" stroke="#cad3d4" stroke-width="7"/><g fill="#11191f" stroke="#52616a" stroke-width="7"><circle cx="347" cy="636" r="89"/><circle cx="927" cy="636" r="89"/></g><g fill="#768891" stroke="#afbdc1" stroke-width="4"><circle cx="347" cy="636" r="53"/><circle cx="927" cy="636" r="53"/></g><g stroke="#253641" stroke-width="13"><path d="m347 590 0 92m-46-46h92m-79-33 66 66m0-66-66 66m613-79v92m-46-46h92m-79-33 66 66m0-66-66 66"/></g><path d="m135 609 100-6v31l-96 2Z" fill="#24343e"/><text x="78" y="225" fill="#dbaf78" font-family="sans-serif" font-size="17" letter-spacing="8">PRECISION / PERFORMANCE / CARE</text></svg>'''

def render_premium_business(brief, project_name):
    auto=brief['kind']=='auto'
    name=escape(brief['name'] or project_name or ('Apex Motorworks' if auto else 'Solara House'))
    location=escape(brief['location'] or 'A place made around you')
    heading='Built for the road.<br><em>Cared for by us.</em>' if auto else 'A slower pace.<br><em>A richer stay.</em>'
    intro='A thoughtful approach to maintenance, diagnostics, and repair. Let’s find the right next step for your vehicle.' if auto else 'Quiet corners, considered spaces, and time that feels like your own. Discover a different kind of getaway.'
    services=brief['services'];cards=''
    descriptions=(['Start with a conversation about your vehicle and the work it needs.','Explore a service plan shaped around your driving routine.','Discuss the details before deciding on the next step.'] if auto else ['A considered space for slowing down and settling in.','Room to unwind, reconnect, and enjoy a little more quiet.','A thoughtful starting point for your next escape.'])
    for i,service in enumerate(services):
        cards+='<article class="service-card"><div class="card-visual variant-'+str(i%3)+'"><span class="card-num">0'+str(i+1)+'</span><div class="visual-window"></div><div class="visual-bed"></div></div><div class="card-content"><p class="eyebrow">'+('CARE, WITHOUT THE GUESSWORK' if auto else 'MAKE YOURSELF AT HOME')+'</p><h3>'+escape(service)+'</h3><p>'+descriptions[i%3]+'</p><button data-service="'+escape(service,quote=True)+'">'+('Plan this service' if auto else 'Plan your stay')+' ↗</button></div></article>'
    contact=''.join('<div><span>'+label.title()+'</span><p>'+escape(brief[label])+'</p></div>' for label in ['location','email','phone'] if brief[label])
    contact=contact or '<p>Add your business contact details before publishing.</p>'
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+name+'''</title><link rel="stylesheet" href="style.css"></head><body class="'''+('automotive' if auto else 'hospitality')+'''"><div class="announcement">'''+('GOOD WORK STARTS WITH A CLEAR CONVERSATION' if auto else 'LESS HURRY. MORE HERE.')+'''<span>'''+location+'''</span></div><nav><a href="#" class="brand"><span class="brand-icon">'''+('A' if auto else 'S')+'''</span>'''+name+'''</a><button id="menu" aria-controls="links" aria-expanded="false">Menu</button><div id="links"><a href="#services">'''+('Our services' if auto else 'Rooms & experiences')+'''</a><a href="#about">Our approach</a><a href="#contact">Find us</a><button class="nav-cta" data-service="">'''+('Plan a service' if auto else 'Plan your stay')+''' ↗</button></div></nav><main><section class="hero"><div class="hero-copy"><p class="eyebrow">'''+('PRECISION IN EVERY DETAIL' if auto else 'A LITTLE CLOSER TO CALM')+'''</p><h1>'''+heading+'''</h1><p class="intro">'''+intro+'''</p><div class="hero-buttons"><button class="cta" data-service="">'''+('Let’s talk about your car' if auto else 'Find your kind of escape')+''' ↗</button><a href="#services" class="text-link">Explore '''+('our services' if auto else 'the collection')+''' ↓</a></div><div class="hero-note"><span>✧</span><p>'''+('Clear communication.<br>A more considered kind of car care.' if auto else 'A stay worth looking forward to.<br>A moment worth making room for.')+'''</p></div></div><div class="hero-art">'''+(AUTO_ART if auto else HOTEL_ART)+'''<span class="image-caption">'''+('THE WORKSHOP EDIT / 01' if auto else 'THE SLOW LIVING COLLECTION / 01')+'''</span><span class="art-badge">'''+('DRIVE<br>WITH<br>CONFIDENCE.' if auto else 'STAY<br>A LITTLE<br>LONGER.')+'''</span></div></section><div class="benefits"><span>'''+('01 &nbsp; Understand the issue' if auto else '01 &nbsp; Space to unwind')+'''</span><span>'''+('02 &nbsp; Discuss your options' if auto else '02 &nbsp; Time to reconnect')+'''</span><span>'''+('03 &nbsp; Plan your next visit' if auto else '03 &nbsp; Details that matter')+'''</span></div><section id="services" class="section"><div class="section-heading"><div><p class="eyebrow">'''+('CARE THAT FITS YOUR DRIVE' if auto else 'YOUR NEXT CHAPTER STARTS HERE')+'''</p><h2>'''+('A better way to<br><em>care for your car.</em>' if auto else 'Make room for<br><em>something wonderful.</em>')+'''</h2></div><p>'''+('Explore the services below. Create a local visit plan, then contact the shop to confirm the details.' if auto else 'Explore the spaces and experiences below. Make a local stay plan, then contact the hotel to confirm availability.')+'''</p></div><div class="services">'''+cards+'''</div></section><section id="about" class="about"><div class="about-art"><span>'''+('↗' if auto else '✳')+'''</span><small>'''+('CARE THAT GOES THE DISTANCE' if auto else 'THE ART OF TAKING YOUR TIME')+'''</small></div><div class="about-copy"><p class="eyebrow">OUR APPROACH</p><h2>'''+('More than a service.<br><em>A conversation.</em>' if auto else 'The little things.<br><em>The lasting feeling.</em>')+'''</h2><p>'''+('Every vehicle has a story. Tell us what you’ve noticed, what you need, and what matters to you. A clear conversation helps shape a better service experience.' if auto else 'A thoughtful stay starts long before you arrive. Tell us what makes a getaway feel right for you, and start planning the moments you want to keep.')+'''</p><a href="#contact" class="text-link">Start a conversation ↗</a></div></section><section class="section faq"><p class="eyebrow">A FEW THINGS TO KNOW</p><h2>Before you '''+('visit.' if auto else 'arrive.')+'''</h2><details><summary>How do I '''+('arrange a service?' if auto else 'plan a stay?')+'''</summary><p>Use the planner to save your preferences in this browser. Contact the business directly to confirm availability, pricing, and arrangements.</p></details><details><summary>Does the planner confirm my booking?</summary><p>No. It saves a local plan only; nothing is sent to the business and no reservation is made.</p></details><details><summary>Can I change my plan later?</summary><p>Yes. Open the planner again in the same browser to edit the saved details.</p></details></section><section id="contact" class="contact-section"><p class="eyebrow">A GOOD PLACE TO START</p><h2>'''+('Let’s keep you moving.' if auto else 'Your next escape awaits.')+'''</h2><div class="contact">'''+contact+'''</div><button class="cta" data-service="">Open your planner ↗</button></section></main><footer><strong>'''+name+'''</strong><span>'''+('Care in every detail.' if auto else 'Stay a little closer to calm.')+'''</span><a href="#">Back to top ↑</a></footer><dialog id="planner"><button id="closePlanner" class="close" aria-label="Close planner">×</button><p class="eyebrow">LET’S MAKE A PLAN</p><h2>'''+('Your next service.' if auto else 'Your next stay.')+'''</h2><p class="planner-note">Local planning only. Nothing is sent or booked.</p><form id="planForm"><label>'''+('Service' if auto else 'Room or experience')+'''<select id="planService">'''+''.join('<option>'+escape(s)+'</option>' for s in services)+'''</select></label><div class="form-row"><label>Preferred date<input id="planDate" type="date" required></label><label>'''+('Vehicle / model<input id="planExtra" placeholder="e.g. Sedan, 2020" maxlength="100" required>' if auto else 'Guests<input id="planExtra" type="number" min="1" max="12" value="2" required>')+'''</label></div><label>Notes<textarea id="planNotes" rows="3" maxlength="1000" placeholder="Anything you would like to discuss?"></textarea></label><button class="cta">Save local plan</button><p id="planStatus" role="status"></p></form></dialog><script src="app.js"></script></body></html>'''
    # The two templates share layout mechanics but have distinct artwork, color, and content.
    css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{--bg:#f8f5ee;--ink:#354337;--muted:#929787;--line:#dce0d2;--accent:#59735a;--surface:#edece1;margin:0;background:var(--bg);color:var(--ink);font:14px Segoe UI,Arial,sans-serif}body.automotive{--bg:#121a20;--ink:#e7eae8;--muted:#8a969d;--line:#303b41;--accent:#c88d54;--surface:#202c33}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer;border:0;background:none;color:inherit}button:hover,a:hover{opacity:.8}:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.announcement{display:flex;justify-content:space-between;padding:11px 5%;background:var(--ink);color:var(--bg);font-size:8px;letter-spacing:2px}.automotive .announcement{background:#c18b56;color:#18232a}nav{display:flex;align-items:center;justify-content:space-between;padding:25px 5%;border-bottom:1px solid var(--line);gap:20px}.brand{font-size:19px;font-weight:650;display:flex;gap:12px;align-items:center;overflow-wrap:anywhere}.brand-icon{font:25px Georgia,serif;border:1px solid var(--accent);width:34px;height:38px;display:grid;place-items:center;color:var(--accent);flex:none}#links{display:flex;align-items:center;gap:30px;font-size:11px}.nav-cta{border:1px solid var(--accent);padding:12px 16px;color:var(--accent)}#menu{display:none}main{max-width:1600px;margin:auto}.hero{display:grid;grid-template-columns:1fr 1.1fr;gap:55px;padding:55px 5% 50px;align-items:center}.eyebrow{font-size:8px;letter-spacing:2px;color:var(--accent);text-transform:uppercase;font-weight:650}h1{font:clamp(42px,4.7vw,72px)/1.07 Georgia,serif;letter-spacing:-2px;margin:24px 0}em{font-weight:400;color:var(--accent)}.intro{font-size:13px;line-height:1.9;color:var(--muted);max-width:380px}.hero-buttons{display:flex;align-items:center;gap:25px;flex-wrap:wrap;margin-top:28px}.cta{display:inline-block;padding:15px 21px;background:var(--accent);color:#fff;font-weight:600;font-size:11px}.automotive .cta{color:#17242b}.text-link{font-size:10px;color:var(--accent);border-bottom:1px solid var(--line);padding-bottom:5px}.hero-note{display:flex;align-items:center;gap:13px;margin-top:29px;color:var(--muted)}.hero-note>span{font-size:32px;color:var(--accent)}.hero-note p{font-size:9px;line-height:1.8}.hero-art{height:490px;position:relative;overflow:hidden;border-radius:140px 140px 4px 4px;background:var(--surface)}.hero-art svg{width:100%;height:100%;object-fit:cover;display:block}.automotive .hero-art{border-radius:5px}.image-caption{position:absolute;left:23px;bottom:20px;font-size:7px;letter-spacing:2px;color:#f8f0dd}.art-badge{position:absolute;right:18px;bottom:40px;background:var(--bg);color:var(--accent);border:1px solid var(--line);width:98px;height:98px;border-radius:50%;display:grid;place-content:center;text-align:center;font-size:9px;line-height:1.6;letter-spacing:1px;transform:rotate(12deg)}.automotive .art-badge{border-radius:4px;transform:rotate(-6deg)}.benefits{display:flex;justify-content:space-between;gap:20px;padding:23px 5%;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:10px;color:var(--muted)}.section{padding:65px 5%}.section-heading{display:flex;align-items:end;justify-content:space-between;gap:35px;margin-bottom:33px}h2{font:clamp(30px,3.5vw,48px)/1.1 Georgia,serif;font-weight:400;letter-spacing:-1px;margin:18px 0}.section-heading>p{font-size:11px;color:var(--muted);line-height:1.9;max-width:285px}.services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px}.service-card{border:1px solid var(--line);min-width:0}.card-visual{height:210px;background:#c4c5ad;position:relative;overflow:hidden}.visual-window{position:absolute;width:32%;height:75%;left:10%;top:0;background:linear-gradient(#adc9c6,#dae0be);border:12px solid #e6dbc2;box-shadow:0 0 0 5px #b3ac92}.visual-bed{position:absolute;width:80%;height:35%;bottom:7%;right:-10%;background:#e9e3d2;border-radius:6px;box-shadow:0 -18px 0 #a8a88b,0 15px 0 #8b8f72}.variant-1{background:#bcac96}.variant-1 .visual-bed{background:#ddd1bd;box-shadow:0 -18px 0 #9e8a74,0 15px 0 #766754}.variant-2{background:#9cae9e}.variant-2 .visual-window{background:linear-gradient(#8faca2,#d2d9b5)}.card-num{position:absolute;right:15px;top:15px;font:24px Georgia,serif;color:#f7f2e6}.automotive .card-visual{background:linear-gradient(130deg,#3d4d55,#19272f)}.automotive .visual-window{height:130px;width:130px;left:calc(50% - 65px);top:35px;background:#14212b;border-radius:50%;border:25px solid #445a66;box-shadow:inset 0 0 0 9px #8c9ba0,12px 16px 25px #0003}.automotive .visual-bed{height:3px;bottom:20px;left:20px;width:40%;background:#ba8956;box-shadow:none}.automotive .variant-1 .visual-window{border-radius:8px;border:15px solid #63747b;transform:rotate(-12deg);background:repeating-linear-gradient(0deg,#14212b 0 9px,#78908e 10px 12px)}.automotive .variant-2 .visual-window{width:150px;height:40px;border-radius:5px;transform:rotate(-30deg);top:80px;left:calc(50% - 75px);border:10px solid #83979e;background:#bd8a59}.card-content{padding:23px}.card-content .eyebrow{font-size:6px}.card-content h3{font:24px Georgia,serif;overflow-wrap:anywhere;margin:15px 0}.card-content>p:not(.eyebrow){font-size:11px;line-height:1.9;color:var(--muted)}.card-content button{font-size:10px;color:var(--accent);padding:10px 0 0}.about{display:grid;grid-template-columns:1fr 1fr;background:var(--surface);gap:50px;align-items:center;margin:0 5%}.about-art{position:relative;height:350px;display:grid;place-items:center;overflow:hidden;background:linear-gradient(120deg,#bbc6af,#dfdec9)}.about-art>span{font-size:280px;line-height:1;color:#879b79;transform:rotate(-15deg)}.about-art small{position:absolute;bottom:25px;left:25px;letter-spacing:2px;font-size:7px;color:#5e7758}.automotive .about-art{background:linear-gradient(120deg,#2d4652,#1f2c35)}.automotive .about-art>span{color:#ae8155}.automotive .about-art small{color:#c49c74}.about-copy{padding:25px 30px 25px 0}.about-copy>p:not(.eyebrow){font-size:12px;line-height:1.9;color:var(--muted);max-width:365px}.about-copy h2{font-size:40px}.about-copy a{display:inline-block;margin-top:15px}.faq{max-width:900px;margin:auto}.faq details{padding:20px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer;font-size:13px}details p{font-size:12px;line-height:1.9;color:var(--muted)}.contact-section{margin:0 5% 60px;padding:40px;background:var(--surface);border:1px solid var(--line);text-align:center}.contact{display:flex;justify-content:center;gap:40px;flex-wrap:wrap;margin:25px 0;overflow-wrap:anywhere}.contact span{font-size:9px;letter-spacing:1px;text-transform:uppercase;color:var(--accent)}.contact p{font-size:12px;color:var(--muted)}footer{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:28px 5%;border-top:1px solid var(--line);font-size:10px;color:var(--muted)}footer strong{font-size:16px;color:var(--ink)}section{scroll-margin-top:20px}dialog{width:480px;max-width:calc(100vw - 28px);max-height:90dvh;overflow:auto;padding:30px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink)}dialog::backdrop{background:#17221faa;backdrop-filter:blur(6px)}.close{position:absolute;top:10px;right:15px;font-size:25px}.planner-note{font-size:11px;color:var(--muted)}dialog label{display:block;font-size:11px;margin:18px 0}dialog input,dialog select,dialog textarea{display:block;width:100%;min-width:0;margin-top:8px;background:var(--surface);color:var(--ink);border:1px solid var(--line);padding:11px;border-radius:5px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form-row label{min-width:0}#planStatus{font-size:11px;line-height:1.7;color:var(--accent)}@media(max-width:900px){.hero{gap:30px}.hero-art{height:430px}#links{gap:17px}.services{gap:15px}.card-content{padding:17px}.about{gap:25px}.about-copy h2{font-size:33px}.section-heading>p{max-width:230px}}@media(max-width:650px){.announcement{font-size:6px;letter-spacing:1px}.announcement>span{display:none}nav{padding:18px 5%;flex-wrap:wrap}.brand{font-size:17px;max-width:78%}#menu{display:block;border:1px solid var(--line);padding:8px 10px;font-size:11px}#links{display:none;width:100%;flex-direction:column;align-items:stretch}#links.open{display:flex}.hero{grid-template-columns:1fr;padding-top:40px;gap:30px}.hero h1{font-size:49px}.hero-art{height:350px;border-radius:95px 95px 4px 4px}.hero-note{margin-top:20px}.hero-buttons{gap:20px}.benefits{font-size:8px;gap:12px;line-height:1.7}.section{padding:45px 5%}.section-heading{display:block}.section-heading>p{max-width:none}.services{grid-template-columns:1fr;gap:22px}.card-visual{height:230px}.card-content{padding:23px}.about{grid-template-columns:1fr;gap:0}.about-art{height:250px}.about-art>span{font-size:225px}.about-copy{padding:25px}.about-copy h2{font-size:35px}.contact-section{padding:30px 20px;margin-bottom:35px}.contact{gap:20px}.contact-section h2{font-size:33px}footer{flex-wrap:wrap;font-size:9px}footer strong{font-size:14px}dialog{padding:25px 20px}.form-row{gap:10px}.art-badge{height:85px;width:85px;font-size:8px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
    js='''const $=id=>document.getElementById(id);const key='business-plan:'+location.pathname;let plan={};try{plan=JSON.parse(localStorage.getItem(key)||'{}');}catch{}$('planDate').min=new Date().toLocaleDateString('en-CA');function openPlanner(service){$('planService').value=service||plan.service||$('planService').options[0].value;$('planDate').value=plan.date||'';$('planExtra').value=plan.extra||$('planExtra').defaultValue||'';$('planNotes').value=plan.notes||'';$('planStatus').textContent='';$('planner').showModal();}document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>openPlanner(b.dataset.service));$('closePlanner').onclick=()=>$('planner').close();$('planForm').onsubmit=e=>{e.preventDefault();const candidate={service:$('planService').value,date:$('planDate').value,extra:$('planExtra').value,notes:$('planNotes').value};try{localStorage.setItem(key,JSON.stringify(candidate));plan=candidate;$('planStatus').textContent='Plan saved in this browser. Contact the business to confirm arrangements; no booking has been made.';}catch{$('planStatus').textContent='Could not save. Browser storage may be unavailable.';}};$('menu').onclick=()=>{const open=$('links').classList.toggle('open');$('menu').setAttribute('aria-expanded',String(open));};$('links').addEventListener('click',()=>{$('links').classList.remove('open');$('menu').setAttribute('aria-expanded','false');});'''
    css += 'body{--accent:'+brief['accent']+'}'
    if brief['dark'] and not auto:
        css += 'body{--bg:#17201e;--ink:#f0eee6;--muted:#9fa99c;--line:#39433d;--surface:#26332b}'
    return html,css,js
